    ld   [0x12], y
    ld   [y,x], ac            ; E
    and  1, ac
    beq  e0_53
    ld   [0x41], ac
    shr  ac
    or   0x80, ac
    bra  ed_54
e0_53:
    ld   [0x41], ac
    shr  ac
ed_54:
    ld   ac, [0x1C]
    and  [0x1B], ac
    ld   ac, [0x40]                ; m1 = L & R
    ld   [0x1C], ac
    xor  [0x1B], ac
    ld   ac, [0x3F]                ; m0 = L ^ R
    xor  [0x41], ac
    ld   ac, [0x3D]                ; a = L ^ C ^ R
    ld   [0x3F], ac
    and  [0x41], ac
    or   [0x40], ac
    ld   ac, [0x3E]                ; b = majority(L, C, R)
    or   [0x3D], ac
    ld   ac, [0x42]                ; o = L | C | R
    bra  rd_55
cz_56:
    ; C = 0: L = W bit 7, R = E bit 0 << 7, so m1 = b = 0, m0 = a = o = L | R
    ld   ac, [0x40]
    ld   ac, [0x3E]
    ld   [0x11], y
    ld   [y,x], ac
    ld   [0x12], y
    or   [y,x], ac
    beq  zk_59                ; W, C and E all 0
    ld   [0x11], y
    ld   [y,x], ac
    blt  zw1_57
    ld   [0x12], y
    ld   [y,x], ac
    and  1, ac
    beq  zk_59
    ld   0x80, ac
    bra  zk_59
zw1_57:
    ld   [0x12], y
    ld   [y,x], ac
    and  1, ac
    beq  zk1_58
    ld   0x81, ac
    bra  zk_59
zk1_58:
    ld   1, ac
zk_59:
    ld   ac, [0x3F]
    ld   ac, [0x3D]
    ld   ac, [0x42]
rd_55:
    nop
    ld   [0x36], ac
    or   [0x3C], ac
    or   [0x42], ac
    beq  zo_60                ; nothing alive nearby: stays 0, no write
    ld   [0x31], ac
    xor  [0x3D], ac
    ld   ac, [0x1D]
    xor  [0x39], ac
    or   [0x3B], ac
    ld   ac, [0x1E]                ; SC = s0 | C
    ld   [0x31], ac
    and  [0x3D], ac
    ld   ac, [0x1F]
    ld   [0x1D], ac
    and  [0x39], ac
    or   [0x1F], ac
    ld   ac, [0x20]                ; CC = carry out of bit 0
    xor  [0x3A], ac
    ld   ac, [0x21]
    ld   [0x20], ac
    and  [0x3A], ac
    ld   ac, [0x22]
    ld   [0x32], ac
    and  [0x3E], ac
    or   [0x22], ac
    not
    ld   ac, [0x23]
    ld   [0x32], ac
    xor  [0x3E], ac
    xor  [0x21], ac
    and  [0x23], ac
    and  [0x1E], ac                ; k == 1 and (s0 | C)
    ld   [0x15], x
    ld   [0x14], y
    ld   ac, [y,x]
zo_60:
    ld   [0x15], ac
    inc
    ld   ac, [0x15]
    inc
    ld   ac, x
    ld   step2 >> 8, y
    jmp  step2
last:
    ; step 479
    ld   fill_7 >> 8, y
    jmp  fill_7
#addr 0x0800
fill_7:
    ld   [0x3C], ac
    or   [0x42], ac
    or   [0x26], ac
    beq  zo_61                ; nothing alive nearby: stays 0, no write
    ld   [0x37], ac
    xor  [0x24], ac
    ld   ac, [0x1D]
    xor  [0x3F], ac
    or   [0x41], ac
    ld   ac, [0x1E]                ; SC = s0 | C
    ld   [0x37], ac
    and  [0x24], ac
    ld   ac, [0x1F]
    ld   [0x1D], ac
    and  [0x3F], ac
    or   [0x1F], ac
    ld   ac, [0x20]                ; CC = carry out of bit 0
    xor  [0x40], ac
    ld   ac, [0x21]
    ld   [0x20], ac
    and  [0x40], ac
    ld   ac, [0x22]
    ld   [0x38], ac
    and  [0x25], ac
    or   [0x22], ac
    not
    ld   ac, [0x23]
    ld   [0x38], ac
    xor  [0x25], ac
    xor  [0x21], ac
    and  [0x23], ac
    and  [0x1E], ac                ; k == 1 and (s0 | C)
    ld   [0x15], x
    ld   [0x10], y
    ld   ac, [y,x]
zo_61:
    ; next column: its W is this column's buffer, buffers A / B alternate
    ld   [0x18], ac
    ld   ac, [0x17]
    sub  0x40, ac
    beq  nc_b
    ld   0x40, ac
    bra  nc_o
nc_b:
    ld   0x42, ac
nc_o:
    ld   ac, [0x18]
    ld   [0x16], ac
    add  2, ac
    ld   ac, [0x16]
    ld   [0x1A], ac
    dec
    ld   ac, [0x1A]
    beq  nc_d
    ld   col >> 8, y
    jmp  col
nc_d:
    nop
    ; generation count
    ld   [0x27], ac
    dec
    ld   ac, [0x27]
    bne  gc_more
    ld   [0x28], ac
    beq  gc_done
    dec
    ld   ac, [0x28]
gc_more:
    ld   gen >> 8, y
    jmp  gen
gc_done:
    nop
    ; about 5 s at 25.175 MHz, less the video stalls
    ld   0xD9, ac
    ld   ac, [0x30]
dly3:
    ld   0x00, ac
    ld   ac, [0x2F]
dly2:
    clr  ac
dly1:
    nop
    dec
    bne  dly1
    ld   [0x2F], ac
    dec
    ld   ac, [0x2F]
    bne  dly2
    ld   [0x30], ac
    dec
    ld   ac, [0x30]
    bne  dly3
    ld   restart >> 8, y
    jmp  restart
